pub fn native_addon_crate_checksums() -> std::collections::BTreeMap<String, String> {
    include_str!("../../../../Cargo.lock")
        .split("[[package]]")
        .filter_map(|package| {
            let field = |name: &str| {
                package.lines().find_map(|line| {
                    line.strip_prefix(&format!("{name} = \""))
                        .and_then(|value| value.strip_suffix('"'))
                })
