            let name = field("name")?;
            if !["napi", "napi-derive", "napi-build"].contains(&name) {
                return None;
            }
            Some((
                format!("{}@{}", name, field("version")?),
                field("checksum")?.to_string(),
            ))
        })
        .collect()
}

